# Shuye launcher entry (ASCII only; the real logic lives in scripts\, generated by tools/make_launcher.py)
$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $MyInvocation.MyCommand.Path

if (-not (Test-Path (Join-Path $root "scripts\launch_window.ps1"))) {
    $py = Join-Path $root "python.exe"
    if (-not (Test-Path $py)) { $py = (Get-Command python -ErrorAction SilentlyContinue).Source }
    if ($py) { & $py (Join-Path $root "tools\make_launcher.py") | Out-Null }
}

& (Join-Path $root "scripts\launch_window.ps1")
